const input = $input.item.json;
const budget = input.budget || 500;
const mvpScope = input.mvp_scope || "Simple user profiles, escrow milestones";

// Inline execution or import of pricing-tool.js
let pricingInsights = "";
try {
  const path = require('path');
  const pricingTool = require(path.resolve(__dirname, '../scripts/pricing-tool.js'));
  pricingInsights = pricingTool.build(budget).text;
} catch (e) {
  if (budget < 1000) {
    pricingInsights = "Low-barrier Freemium: Focus on transaction cut-rates (2-3%) rather than high monthly retainers.";
  } else {
    pricingInsights = "Three-Tier Pricing: Standard free tier, $19/mo professional tier, $79/mo agency tier.";
  }
}

return {
  json: {
    prompt: `Draft a timeline for MVP build. Budget restrictions: ${pricingInsights}. Scope: ${mvpScope}`,
    model: "gpt-4o-mini"
  }
};
